const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Houston geometry
  const houston = ee.Geometry.Point([-95.3698, 29.7604]).buffer(20000); // 20km radius

  // 2. Data Acquisition
  const collection = ee.ImageCollection('VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterBounds(houston)
    .select('avg_rad');

  // December 2012 and 2013
  const dec2012 = collection.filterDate('2012-12-01', '2012-12-31');
  const dec2013 = collection.filterDate('2013-12-01', '2013-12-31');

  // Other months (Jan-Nov 2012, Jan-Nov 2013, all 2014)
  const other2012 = collection.filterDate('2012-01-01', '2012-11-30');
  const other2013 = collection.filterDate('2013-01-01', '2013-11-30');
  const all2014 = collection.filterDate('2014-01-01', '2014-12-31');

  // Check collection sizes
  const dec2012Size = dec2012.size().getInfo();
  const dec2013Size = dec2013.size().getInfo();
  const other2012Size = other2012.size().getInfo();
  const other2013Size = other2013.size().getInfo();
  const all2014Size = all2014.size().getInfo();

  console.log(`Dec 2012: ${dec2012Size} images, Dec 2013: ${dec2013Size} images`);
  console.log(`Other 2012: ${other2012Size}, Other 2013: ${other2013Size}, All 2014: ${all2014Size} images`);

  if (dec2012Size === 0 || dec2013Size === 0 || (other2012Size + other2013Size + all2014Size) === 0) {
    console.log('Missing data for comparison periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate mean values
  const decemberImages = dec2012.merge(dec2013);
  const otherImages = other2012.merge(other2013).merge(all2014);

  const decMean = decemberImages.mean();
  const otherMean = otherImages.mean();

  // 4. Reduce to region
  const decStats = decMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const otherStats = otherMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const decValue = decStats.avg_rad_mean;
  const decCount = decStats.avg_rad_count;
  const otherValue = otherStats.avg_rad_mean;
  const otherCount = otherStats.avg_rad_count;

  console.log(`December avg: ${decValue}, pixels: ${decCount}`);
  console.log(`Other months avg: ${otherValue}, pixels: ${otherCount}`);

  // 5. Validation & Answer
  if (decCount === 0 || otherCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (decValue === null || decValue === undefined || otherValue === null || otherValue === undefined) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (decValue > otherValue) {
    console.log(`December (${decValue.toFixed(2)}) > Other months (${otherValue.toFixed(2)})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`December (${decValue.toFixed(2)}) <= Other months (${otherValue.toFixed(2)})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
